// 1. Clean foreign keys if any
msg.remove("m3Air");
msg.remove("m3LPG");
msg.remove("delta_CO2");

var tsMs = metadata.ts != null ? Long.parseLong(metadata.ts.toString()) : System.currentTimeMillis();
var qStr = msg.quality != null ? msg.quality.toString().trim().toUpperCase() : "";
var errStr = msg.errorReason != null ? msg.errorReason.toString().trim() : "";
var hasProcessData = (msg.temperature != null || msg.kwh != null || msg.kWh != null || msg.p_total != null || msg.status != null || msg.run != null);

// 2. Detect Gateway / Modbus / PLC Communication Failure (quality == BAD or error frame without process data)
if (qStr.equals("BAD") || (!errStr.isEmpty() && !hasProcessData)) {
    var faultRoutes = ["Comm_Fault_Route"];
    // Still trigger Energy_Route for Power_Meter so Calendar Rollover resets kwh_today/week/month to 0 on a new day/week/month!
    if (metadata.deviceType != null && metadata.deviceType.toString().equals("Power_Meter")) {
        faultRoutes.add("Energy_Route");
    }
    return faultRoutes;
}

// 3. Valid Telemetry received -> mark ONLINE & clear any active communication fault alarm
msg.quality = "GOOD";
msg.comm_status = "ONLINE";
msg.errorReason = "";
msg.last_good_ts = tsMs;

var routes = ["Valid_Telemetry", "Comm_Restored_Route"];

// 4. PT100 Temperature Spike & Open/Short Circuit Hardware Guard (-45°C .. +160°C)
if (msg.temperature != null) {
    var t = Double.parseDouble(msg.temperature.toString());
    if (t < -45.0 || t > 160.0) {
        msg.quality = "BAD";
        msg.comm_status = "SENSOR_FAULT";
        msg.errorReason = "PT100_WIRE_FAULT:" + t + "C";
