var statusStr = msg.status != null ? msg.status.toString().trim().toUpperCase() : "";
var isRun = (statusStr == "RUNNING" || statusStr == "ON" || statusStr == "1" || statusStr == "1.0" || statusStr == "TRUE" || msg.run == 1 || msg.run == true);
var curStInt = isRun ? 1 : 0;

var tsMs = metadata.ts != null ? Long.parseLong(metadata.ts.toString()) : System.currentTimeMillis();
var lastTs = metadata.ss_last_run_ts != null ? Long.parseLong(metadata.ss_last_run_ts.toString()) : tsMs;
var lastChangeTs = metadata.ss_last_state_change_ts != null ? Long.parseLong(metadata.ss_last_state_change_ts.toString()) : lastTs;
var prevStInt = metadata.ss_last_status != null ? Integer.parseInt(metadata.ss_last_status.toString()) : curStInt;

var lifeHrs = metadata.ss_runtime_lifetime_hours != null ? Double.parseDouble(metadata.ss_runtime_lifetime_hours.toString()) : 0.0;
var cycleHrs = metadata.ss_runtime_hours_total != null ? Double.parseDouble(metadata.ss_runtime_hours_total.toString()) : 0.0;
var contHrs = metadata.ss_continuous_run_hours != null ? Double.parseDouble(metadata.ss_continuous_run_hours.toString()) : 0.0;
var maintLimit = metadata.ss_maintenance_limit_hours != null ? Double.parseDouble(metadata.ss_maintenance_limit_hours.toString()) : 1000.0;
var startCnt = metadata.ss_start_count_total != null ? Integer.parseInt(metadata.ss_start_count_total.toString()) : 0;
var stopCnt = metadata.ss_stop_count_total != null ? Integer.parseInt(metadata.ss_stop_count_total.toString()) : 0;

var dtHrs = (tsMs - lastTs) / 3600000.0;
if (dtHrs < 0.0 || dtHrs > 24.0) {
    dtHrs = 0.0;
}

if (isRun) {
    lifeHrs = Math.round((lifeHrs + dtHrs) * 100.0) / 100.0;
    cycleHrs = Math.round((cycleHrs + dtHrs) * 100.0) / 100.0;
    contHrs = Math.round((contHrs + dtHrs) * 100.0) / 100.0;
} else {
    contHrs = 0.0;
}

var outMsg = {
    "last_run_ts": tsMs,
    "last_status": curStInt,
    "runtime_lifetime_hours": lifeHrs,
    "runtime_hours_total": cycleHrs,
    "continuous_run_hours": contHrs,
    "maintenance_due": (cycleHrs >= maintLimit)
};

if (curStInt != prevStInt && tsMs > lastChangeTs) {
    var durSec = Math.max(1L, Math.round((tsMs - lastChangeTs) / 1000.0));
    var durStr = "";
    if (durSec < 60L) {
        durStr = durSec + " giây";
    } else if (durSec < 3600L) {
        var m = toInt(durSec / 60L);
        var s = durSec % 60L;
        durStr = m + "p" + (s > 0L ? " " + s + "s" : "");
    } else {
        var h = toInt(durSec / 3600L);
        var rm = toInt((durSec % 3600L) / 60L);
        durStr = h + "h " + rm + "p";
    }

    if (isRun) {
        startCnt = startCnt + 1;
        outMsg.start_count_total = startCnt;
        outMsg.switch_event_type = "START";
        outMsg.switch_cycle_sec = durSec;
        outMsg.switch_event_text = "Đóng contactor khởi động (Sau " + durStr + " nghỉ)";
    } else {
        stopCnt = stopCnt + 1;
        outMsg.stop_count_total = stopCnt;
        outMsg.switch_event_type = "STOP";
        outMsg.switch_cycle_sec = durSec;
        outMsg.switch_event_text = "Ngắt contactor dừng máy (Chu kỳ chạy " + durStr + ")";
    }
    outMsg.last_state_change_ts = tsMs;
} else if (metadata.ss_last_state_change_ts == null) {
    outMsg.last_state_change_ts = tsMs;
}

return {msg: outMsg, metadata: metadata, msgType: "POST_TELEMETRY_REQUEST"};

